        "APS": "7e3487927f6d3ef48a6d3193e0b494aa",
        "CON": null,
        "MNE": "2df7c1a3cbbc6ae411fe86ef5ed84340",
        "CFG": "b9a8ec1c9df29a16352b11099f626d6b",
